export function addWindow(parent, {
  x = 0, y = 0, z = 0, w = 1.5, h = 2, lit = false, color = 0xffb56a,
  rotY = 0, hollow = false, frameMat = null, glassMat = null
} = {}) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  g.rotation.y = rotY;
  const fm = frameMat || std(0x181512, { roughness: 0.6 });
  box(g, w + 0.28, h + 0.28, 0.16, fm, 0, 0, 0, [0, 0, 0]);
  const glass = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    glassMat || new THREE.MeshStandardMaterial({
      color: hollow ? 0x2a0806 : (lit ? 0x6f4b25 : 0x0a1119),
      emissive: hollow ? 0x5e0b06 : (lit ? 0xff9c45 : 0x030608),
      emissiveIntensity: hollow ? 1.4 : (lit ? 0.55 : 0.15),
      roughness: 0.2, metalness: 0.1
    })
  );
  glass.position.z = 0.09;
  g.add(glass);
  const barMat = fm;
  box(g, 0.05, h, 0.1, barMat, 0, 0, 0.1);
  box(g, w, 0.05, 0.1, barMat, 0, 0, 0.1);
  box(g, w, 0.07, 0.18, fm, 0, h / 2 + 0.06, 0.04);
  parent.add(g);
  return { group: g, glass };
}

export function buildTree(seed = 1, height = 9, color = 0x161616) {
  const rnd = mulberry32(seed);
  const g = new THREE.Group();
  const mat = std(color, { roughness: 0.95 });
  const branch = (start, dir, len, radius, depth) => {
    const end = start.clone().addScaledVector(dir, len);
    const mesh = cylinderBetween(start, end, radius, radius * 0.55, mat, 5);
    mesh.castShadow = true;
    g.add(mesh);
    if (depth <= 0) return;
    const n = depth > 2 ? 3 : 2;
    for (let i = 0; i < n; i++) {
      const nd = dir.clone();
      nd.x += (rnd() - 0.5) * 1.1;
      nd.z += (rnd() - 0.5) * 1.1;
      nd.y = Math.abs(nd.y) * (0.75 + rnd() * 0.4);
      nd.normalize();
      branch(end, nd, len * (0.55 + rnd() * 0.22), radius * 0.56, depth - 1);
    }
  };
  branch(new THREE.Vector3(0, 0, 0), new THREE.Vector3((rnd() - 0.5) * 0.2, 1, (rnd() - 0.5) * 0.2).normalize(), height * 0.46, height * 0.045, 4);
  return g;
}

export function buildHouse({ hollow = false } = {}) {
  const g = new THREE.Group();
  const siding = new THREE.MeshStandardMaterial({
    map: sidingTexture(), color: hollow ? 0x3a3232 : 0x8b9188,
    roughness: 0.88, metalness: 0.02
  });
  const trim = std(hollow ? 0x171416 : 0x24261f, { roughness: 0.8 });
  const roofMat = new THREE.MeshStandardMaterial({ map: shingleTexture(), color: hollow ? 0x2c2626 : 0x8b8d8e, roughness: 0.92 });
  const dark = std(hollow ? 0x0d0a0a : 0x15130f);

  // main body
  box(g, 13, 4.3, 9, siding, 0, 2.15, -2);
  box(g, 12.4, 3.7, 8.2, siding, 0, 5.9, -2.3);
  // foundation
  box(g, 13.3, 0.55, 9.3, std(0x1b1b1a, { roughness: 0.95 }), 0, 0.27, -2);

  // roof planes
  const slope = 0.68;
  const roofL = box(g, 7.9, 0.28, 9.8, roofMat, -3.6, 8.15, -2.1, [0, 0, slope]);
  const roofR = box(g, 7.9, 0.28, 9.8, roofMat, 3.6, 8.15, -2.1, [0, 0, -slope]);
  if (hollow) {
    roofL.rotation.z = 0.42;
    roofL.position.y = 7.7;
    roofL.position.x = -4.3;
    roofR.rotation.x = 0.08;
  }
  // gable triangle (front)
  const triShape = new THREE.Shape();
  triShape.moveTo(-6.5, 0); triShape.lineTo(6.5, 0); triShape.lineTo(0, 3.2); triShape.lineTo(-6.5, 0);
  const triGeo = new THREE.ExtrudeGeometry(triShape, { depth: 0.2, bevelEnabled: false });
  const tri = new THREE.Mesh(triGeo, siding);
  tri.position.set(0, 7.15, 2.35);
  tri.castShadow = true;
  g.add(tri);
  // chimney
  box(g, 1.1, 3.4, 1.1, std(hollow ? 0x1a1716 : 0x4b3430), 4.2, 9.2, -4.5);

  // porch
  box(g, 7.2, 0.22, 3.4, std(0x211c17, { roughness: 0.9 }), 0, 0.55, 3.4);
  box(g, 7.4, 0.2, 0.35, trim, 0, 0.66, 5.1);
  for (const x of [-3.2, -1.1, 1.1, 3.2]) {
    box(g, 0.24, 3.1, 0.24, trim, x, 2.15, 4.85);
  }
  box(g, 7.4, 0.22, 3.6, roofMat, 0, 3.75, 3.45, [-0.07, 0, 0]);
  // steps
  for (let i = 0; i < 3; i++) {
    box(g, 4.2, 0.18, 0.55, std(0x2b2620), 0, 0.14 + i * 0.18, 5.55 + (2 - i) * 0.55);
  }

  // front door
  box(g, 2.1, 3.15, 0.2, trim, 0, 1.9, 2.5);
  const door = box(g, 1.7, 2.85, 0.16, std(hollow ? 0x120d0c : 0x2a1911, { roughness: 0.65 }), 0, 1.8, 2.62);
  door.castShadow = true;
  const knob = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 8), std(0x8f7a4a, { metalness: 0.8, roughness: 0.3 }));
  knob.position.set(0.65, 1.8, 2.72);
  g.add(knob);
  // fanlight
  const fan = new THREE.Mesh(
    new THREE.CircleGeometry(0.62, 20, 0, Math.PI),
    new THREE.MeshStandardMaterial({ color: 0x332414, emissive: hollow ? 0x6a0a06 : 0xffbe76, emissiveIntensity: hollow ? 1.2 : 0.5, roughness: 0.3 })
  );
  fan.position.set(0, 3.63, 2.6);
  fan.rotation.z = Math.PI;
  g.add(fan);

  // windows
  addWindow(g, { x: -4.2, y: 2.5, z: 2.53, w: 1.5, h: 2.2, lit: !hollow, hollow });
  addWindow(g, { x: 4.2, y: 2.5, z: 2.53, w: 1.5, h: 2.2, lit: !hollow, hollow });
  addWindow(g, { x: -4.0, y: 6.2, z: 1.72, w: 1.35, h: 1.9, lit: false, hollow });
  addWindow(g, { x: 4.0, y: 6.2, z: 1.72, w: 1.35, h: 1.9, lit: false, hollow });
  addWindow(g, { x: 0, y: 8.15, z: 2.5, w: 1.1, h: 1.3, lit: false, hollow });
  // side windows
  addWindow(g, { x: -6.53, y: 2.7, z: -2.4, w: 1.4, h: 2.1, rotY: Math.PI / 2, lit: false, hollow });
  addWindow(g, { x: 6.53, y: 2.7, z: -2.4, w: 1.4, h: 2.1, rotY: -Math.PI / 2, lit: false, hollow });
  addWindow(g, { x: -6.53, y: 6.2, z: -2.4, w: 1.3, h: 1.8, rotY: Math.PI / 2, lit: false, hollow });
  addWindow(g, { x: 6.53, y: 6.2, z: -2.4, w: 1.3, h: 1.8, rotY: -Math.PI / 2, lit: false, hollow });

  // porch light
  const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.13, 10, 10), new THREE.MeshStandardMaterial({
    color: 0xffd9a0, emissive: hollow ? 0x5c0b06 : 0xffa64b, emissiveIntensity: hollow ? 1.6 : 3
  }));
  lamp.position.set(0.95, 3.2, 2.9);
  g.add(lamp);
  if (!hollow) {
    const pl = new THREE.PointLight(0xffa258, 9, 11, 2);
    pl.position.set(0.95, 3.2, 3.1);
    g.add(pl);
    spriteGlow(g, 0xffb066, 1.5, 0.35, [0.95, 3.2, 2.95]);
  } else {
    const pl = new THREE.PointLight(0xff351f, 12, 14, 2);
    pl.position.set(0.95, 3.2, 3.1);
    g.add(pl);
    spriteGlow(g, 0xff4422, 2.6, 0.45, [0.95, 3.2, 2.95]);
  }

  // house number
  const num = canvasTexture(128, 96, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#d8c9a8';
    ctx.font = '600 54px "Cormorant Garamond", serif';
    ctx.textAlign = 'center';
    ctx.fillText('37', w / 2, 66);
  }, { repeat: [1, 1] });
  const numMesh = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.38), new THREE.MeshBasicMaterial({ map: num, transparent: true }));
  numMesh.position.set(1.55, 2.9, 2.55);
  g.add(numMesh);

  // bushes / neglect
  const bushMat = std(hollow ? 0x0c0a0a : 0x1d261c, { roughness: 1 });
  const rnd = mulberry32(71);
  for (let i = 0; i < 9; i++) {
    const side = i % 2 ? 1 : -1;
    const b = new THREE.Mesh(new THREE.IcosahedronGeometry(0.5 + rnd() * 0.65, 1), bushMat);
    b.position.set(side * (3.3 + rnd() * 3.4), 0.5 + rnd() * 0.3, 2.4 + rnd() * 0.9);
    b.scale.set(1, 0.75, 1);
    b.castShadow = true;
    g.add(b);
  }

  // vines for hollow
  if (hollow) {
    const vineMat = std(0x1a0a08, { roughness: 0.9 });
    for (let i = 0; i < 12; i++) {
      const pts = [];
      let x = -6 + rnd() * 12, y = 8.6, z = 2.6;
      for (let j = 0; j < 6; j++) {
        pts.push(new THREE.Vector3(x + (rnd() - 0.5) * 1.4, y, z + (rnd() - 0.5) * 0.4));
        y -= 0.55 + rnd() * 0.9;
        x += (rnd() - 0.5) * 0.8;
      }
      const curve = new THREE.CatmullRomCurve3(pts);
      const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 20, 0.025 + rnd() * 0.045, 4, false), vineMat);
      g.add(tube);
      // leaves / pods
      for (let k = 1; k < pts.length - 1; k += 2) {
        const pod = new THREE.Mesh(new THREE.SphereGeometry(0.05 + rnd() * 0.06, 5, 4), std(0x2b0b08));
        pod.position.copy(pts[k]).add(new THREE.Vector3((rnd() - 0.5) * 0.2, 0, 0.05));
        g.add(pod);
      }
    }
  }

  return { group: g, roofL, roofR };
}

export function makeGround(size = 180, color = 0x0a0f0c, roughness = 0.9) {
  const mat = new THREE.MeshStandardMaterial({ color, roughness, metalness: 0.08 });
  const m = new THREE.Mesh(new THREE.PlaneGeometry(size, size), mat);
  m.rotation.x = -Math.PI / 2;
  m.receiveShadow = true;
  return m;
}

export function makePuddle(size = 4, color = 0x1b2a30) {
  const mat = new THREE.MeshStandardMaterial({
    color, roughness: 0.06, metalness: 0.6, transparent: true, opacity: 0.65
  });
  const m = new THREE.Mesh(new THREE.CircleGeometry(size, 26), mat);
  m.rotation.x = -Math.PI / 2;
  m.position.y = 0.012;
  return m;
}

import * as THREE from 'three';
import { std } from './props.js';

const SKIN = 0xc9a184;
const HAIR = 0x2a1d16;

function limb(parent, radius, length, material, x = 0, y = 0, z = 0) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  const geo = new THREE.CapsuleGeometry(radius, Math.max(0.01, length - radius * 2), 4, 8);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.y = -length / 2;
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  g.add(mesh);
  parent.add(g);
  return g;
}

export function createPerson({
  name = 'RYAN',
  height = 1.76,
  skin = SKIN,
  hair = HAIR,
  hairStyle = 'short',
  jacket = 0x2d3a44,
  shirt = 0x1c1e22,
  pants = 0x24262a,
  shoes = 0x121212,
  flashlight = false,
  pose = 'stand',
  scale = 1
} = {}) {
  const root = new THREE.Group();
  root.name = `actor-${name}`;
  root.scale.setScalar(scale * (height / 1.76));
  const body = new THREE.Group();
  root.add(body);

  const skinMat = std(skin, { roughness: 0.72 });
  const hairMat = std(hair, { roughness: 0.85 });
  const jacketMat = std(jacket, { roughness: 0.88 });
  const shirtMat = std(shirt, { roughness: 0.9 });
  const pantsMat = std(pants, { roughness: 0.94 });
  const shoeMat = std(shoes, { roughness: 0.6 });
  const dark = std(0x0a0a0b, { roughness: 0.8 });

  const hipY = 0.82;
  const legLen = 0.78;
  const thighLen = 0.39;

  const hips = new THREE.Group();
  hips.position.y = hipY;
  body.add(hips);

  // legs
  const thighL = limb(hips, 0.085, thighLen, pantsMat, -0.115, 0, 0);
  const thighR = limb(hips, 0.085, thighLen, pantsMat, 0.115, 0, 0);
  const shinL = limb(thighL, 0.066, thighLen, pantsMat, 0, -thighLen, 0);
  const shinR = limb(thighR, 0.066, thighLen, pantsMat, 0, -thighLen, 0);
  const footL = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.1, 0.26), shoeMat);
  footL.position.set(0, -legLen - 0.02, 0.055);
  footL.castShadow = true;
  shinL.add(footL);
  const footR = footL.clone();
  footR.position.x = 0;
  shinR.add(footR);

  // torso
  const torso = new THREE.Group();
  torso.position.y = hipY + 0.04;
  body.add(torso);
  const torsoMesh = new THREE.Mesh(new THREE.CapsuleGeometry(0.185, 0.42, 5, 10), jacketMat);
  torsoMesh.position.y = 0.23;
  torsoMesh.scale.set(1.2, 1, 0.72);
  torsoMesh.castShadow = true;
  torso.add(torsoMesh);
  // shirt / zipper
  const zip = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.43, 0.02), dark);
  zip.position.set(0, 0.24, 0.142);
  torso.add(zip);
  // collar
  const collar = new THREE.Mesh(new THREE.TorusGeometry(0.115, 0.02, 5, 12, Math.PI), shirtMat);
  collar.rotation.x = Math.PI / 2;
  collar.position.y = 0.47;
  torso.add(collar);
  // shoulders
  const shoulderL = new THREE.Group(); shoulderL.position.set(-0.21, 0.42, 0); torso.add(shoulderL);
  const shoulderR = new THREE.Group(); shoulderR.position.set(0.21, 0.42, 0); torso.add(shoulderR);

  const armL = limb(shoulderL, 0.06, 0.3, jacketMat, 0, 0, 0);
  const armR = limb(shoulderR, 0.06, 0.3, jacketMat, 0, 0, 0);
  const foreL = limb(armL, 0.05, 0.28, jacketMat, 0, -0.3, 0);
  const foreR = limb(armR, 0.05, 0.28, jacketMat, 0, -0.3, 0);
  const handL = new THREE.Mesh(new THREE.SphereGeometry(0.058, 8, 6), skinMat);
  handL.position.y = -0.29;
  foreL.add(handL);
  const handR = new THREE.Mesh(new THREE.SphereGeometry(0.058, 8, 6), skinMat);
  handR.position.y = -0.29;
  foreR.add(handR);

  // neck + head
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.06, 0.1, 7), skinMat);
  neck.position.y = 0.51;
  torso.add(neck);
  const head = new THREE.Group();
  head.position.y = 0.61;
  torso.add(head);
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.115, 18, 16), skinMat);
  skull.scale.set(0.92, 1.08, 0.94);
  skull.castShadow = true;
  head.add(skull);
  // jaw / chin
  const jaw = new THREE.Mesh(new THREE.SphereGeometry(0.082, 12, 10), skinMat);
  jaw.position.set(0, -0.065, 0.015);
  jaw.scale.set(0.88, 0.7, 0.9);
  head.add(jaw);
  // nose
  const nose = new THREE.Mesh(new THREE.ConeGeometry(0.018, 0.05, 5), skinMat);
  nose.rotation.x = Math.PI / 2;
  nose.position.set(0, -0.01, 0.108);
  head.add(nose);
  // eyes
  const eyeMat = std(0x100c0a, { roughness: 0.3 });
  for (const s of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.012, 6, 6), eyeMat);
    eye.position.set(s * 0.038, 0.015, 0.099);
    head.add(eye);
    const brow = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.009, 0.012), hairMat);
    brow.position.set(s * 0.04, 0.046, 0.1);
    brow.rotation.z = s * 0.08;
    head.add(brow);
  }
  // hair
  if (hairStyle === 'long') {
    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.127, 16, 14), hairMat);
    cap.scale.set(1.02, 1.05, 1.02);
    cap.position.y = 0.018;
    head.add(cap);
    const back = new THREE.Mesh(new THREE.CapsuleGeometry(0.09, 0.2, 4, 8), hairMat);
    back.position.set(0, -0.1, -0.045);
    back.scale.set(1.1, 1, 0.55);
    head.add(back);
    for (const s of [-1, 1]) {
      const strand = new THREE.Mesh(new THREE.CapsuleGeometry(0.035, 0.2, 4, 6), hairMat);
      strand.position.set(s * 0.1, -0.1, 0.015);
      strand.rotation.z = s * 0.08;
      head.add(strand);
    }
  } else if (hairStyle === 'curly') {
    for (let i = 0; i < 14; i++) {
      const clump = new THREE.Mesh(new THREE.SphereGeometry(0.045 + Math.random() * 0.02, 7, 6), hairMat);
      const a = (i / 14) * Math.PI * 2;
      clump.position.set(Math.cos(a) * 0.09, 0.07 + Math.sin(i) * 0.025, Math.sin(a) * 0.07);
      head.add(clump);
    }
  } else {
    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.123, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.62), hairMat);
    cap.position.y = 0.014;
    cap.scale.set(1.0, 1.05, 1.02);
    head.add(cap);
    const fringe = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.04, 0.05), hairMat);
    fringe.position.set(0, 0.088, 0.085);
    fringe.rotation.x = -0.18;
    head.add(fringe);
  }

  // flashlight
  let flashlightRig = null;
  if (flashlight) {
    flashlightRig = new THREE.Group();
    flashlightRig.position.set(0, -0.29, 0.02);
    foreR.add(flashlightRig);
    const bodyMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.03, 0.22, 8), std(0x1a1a1c, { metalness: 0.6, roughness: 0.35 }));
    bodyMesh.rotation.x = Math.PI / 2;
    bodyMesh.position.z = 0.1;
    flashlightRig.add(bodyMesh);
    const lens = new THREE.Mesh(new THREE.CircleGeometry(0.033, 10), new THREE.MeshBasicMaterial({ color: 0xfff2cf }));
    lens.position.z = 0.215;
    flashlightRig.add(lens);
    const light = new THREE.SpotLight(0xffe0b0, flashlight === true ? 22 : 16, 18, 0.44, 0.6, 1.4);
    light.position.set(0, 0, 0.2);
    light.castShadow = false;
    const target = new THREE.Object3D();
    target.position.set(0, -0.1, 4);
    flashlightRig.add(target);
    light.target = target;
    flashlightRig.add(light);
    flashlightRig.rotation.x = 0.28;
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: null, color: 0xffe8c0, transparent: true, opacity: 0.28,
      blending: THREE.AdditiveBlending, depthWrite: false
    }));
    glow.scale.setScalar(0.22);
    glow.position.z = 0.22;
    flashlightRig.add(glow);
  }

  // pose
  const base = {
    shoulderL: 0.1, shoulderR: -0.1,
    armL: 0.08, armR: -0.08,
    foreL: 0.18, foreR: 0.18,
    thighL: 0, thighR: 0,
    shinL: 0, shinR: 0,
    headX: 0, headY: 0, bodyX: 0
  };
  const applied = { ...base };
  let walkPhase = 0;
  let walking = 0;
  let float = 0;

  const setPose = (p) => {
    applied.bodyX = 0;
    applied.thighL = 0; applied.thighR = 0;
    applied.shinL = 0; applied.shinR = 0;
    applied.armL = 0.08; applied.armR = -0.08;
    applied.foreL = 0.18; applied.foreR = 0.18;
    applied.shoulderL = 0.1; applied.shoulderR = -0.1;
    applied.headX = 0; applied.headY = 0;
    hips.position.y = hipY;
    if (p === 'slump') {
      applied.bodyX = 0.06;
      applied.headX = 0.25;
      applied.shoulderL = 0.24; applied.shoulderR = -0.24;
    } else if (p === 'sit') {
      hips.position.y = hipY;
      applied.thighL = -Math.PI / 2 + 0.06; applied.thighR = -Math.PI / 2 - 0.06;
      applied.shinL = Math.PI / 2; applied.shinR = Math.PI / 2;
      applied.armL = 0.4; applied.armR = -0.4;
      applied.foreL = 0.9; applied.foreR = 0.9;
    } else if (p === 'reach') {
      applied.armR = -1.3; applied.foreR = 0.1; applied.shoulderR = -0.35;
      applied.headX = -0.12;
    } else if (p === 'hold') {
      applied.armL = 1.0; applied.armR = -1.0; applied.foreL = 0.7; applied.foreR = 0.7;
      applied.shoulderL = 0.36; applied.shoulderR = -0.36;
    } else if (p === 'cover') {
      applied.armL = 1.5; applied.armR = -1.5; applied.shoulderL = 0.5; applied.shoulderR = -0.5;
      applied.foreL = 1.6; applied.foreR = 1.6;
      applied.headX = 0.2;
    } else if (p === 'fear') {
      applied.bodyX = -0.05;
      applied.armL = 0.4; applied.armR = -0.4;
      applied.shoulderL = 0.3; applied.shoulderR = -0.3;
      applied.headX = -0.12;
    } else if (p === 'point') {
      applied.armR = -1.55; applied.foreR = 0.05;
    } else if (p === 'kneel') {
      hips.position.y = hipY - 0.36;
      applied.thighL = -1.35; applied.thighR = 0.3;
      applied.shinL = 1.5; applied.shinR = 0.2;
      applied.headX = 0.15;
    } else if (p === 'collapsed') {
      body.rotation.z = 0.04;
      hips.position.y = hipY - 0.48;
      applied.thighL = -1.1; applied.thighR = -0.7;
      applied.shinL = 1.2; applied.shinR = 1.4;
      applied.armL = 1.1; applied.armR = -0.5;
      applied.foreL = 1.4;
      applied.headX = 0.35;
    }
  };
  setPose(pose);

  const update = (t, dt = 0.016) => {
    if (walking > 0.01) {
      walkPhase += dt * 5.8 * walking;
      applied.thighL = Math.sin(walkPhase) * 0.65;
      applied.thighR = -Math.sin(walkPhase) * 0.65;
      applied.shinL = Math.max(0, -Math.sin(walkPhase)) * 0.7;
      applied.shinR = Math.max(0, Math.sin(walkPhase)) * 0.7;
      applied.armL = -Math.sin(walkPhase) * 0.5;
      applied.armR = Math.sin(walkPhase) * 0.5;
    }
    const breath = Math.sin(t * 1.4 + root.position.x * 0.7) * 0.008;
    const sway = Math.sin(t * 0.53 + root.position.z * 0.3) * 0.014;
    body.position.y = float + breath;
    body.rotation.x += (applied.bodyX - body.rotation.x) * Math.min(1, dt * 6);
    hips.rotation.x += ((applied.bodyX * 0.3) - hips.rotation.x) * Math.min(1, dt * 6);
    thighL.rotation.x += (applied.thighL - thighL.rotation.x) * Math.min(1, dt * 7);
    thighR.rotation.x += (applied.thighR - thighR.rotation.x) * Math.min(1, dt * 7);
    shinL.rotation.x += (applied.shinL - shinL.rotation.x) * Math.min(1, dt * 7);
    shinR.rotation.x += (applied.shinR - shinR.rotation.x) * Math.min(1, dt * 7);
    shoulderL.rotation.z += (applied.shoulderL - shoulderL.rotation.z) * Math.min(1, dt * 6);
    shoulderR.rotation.z += (applied.shoulderR - shoulderR.rotation.z) * Math.min(1, dt * 6);
    armL.rotation.z += (applied.armL + sway - armL.rotation.z) * Math.min(1, dt * 5);
    armR.rotation.z += (applied.armR - sway - armR.rotation.z) * Math.min(1, dt * 5);
    foreL.rotation.x += (applied.foreL - foreL.rotation.x) * Math.min(1, dt * 6);
    foreR.rotation.x += (applied.foreR - foreR.rotation.x) * Math.min(1, dt * 6);
    head.rotation.x += (applied.headX + Math.sin(t * 0.7) * 0.012 - head.rotation.x) * Math.min(1, dt * 4);
    head.rotation.y += (applied.headY + Math.sin(t * 0.33 + 1) * 0.03 - head.rotation.y) * Math.min(1, dt * 4);
  };

  const api = {
    root, body, head, torso, flashlightRig,
    setPose,
    update,
    setWalking(v) { walking = v; },
    setFloat(v) { float = v; },
    lookAtYaw(y) { applied.headY = y; },
    setPosition(x, y, z) { root.position.set(x, y, z); },
    setRotation(y) { root.rotation.y = y; }
  };
  return api;
}

export function createHollowMan() {
  const root = new THREE.Group();
  const dark = std(0x0b0808, { roughness: 0.72, metalness: 0.12 });
  const skin = std(0x2a1e1c, { roughness: 0.9 });
  const vein = new THREE.MeshStandardMaterial({ color: 0x2a0606, emissive: 0x9e0f08, emissiveIntensity: 1.4, roughness: 0.7 });
  const body = new THREE.Group();
  root.add(body);
  // long torso
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.21, 0.85, 6, 10), dark);
  torso.position.y = 2.1;
  torso.scale.set(0.82, 1, 0.55);
  body.add(torso);
  // ribs
  for (let i = 0; i < 4; i++) {
    const rib = new THREE.Mesh(new THREE.TorusGeometry(0.18 - i * 0.012, 0.012, 5, 12, Math.PI * 1.25), skin);
    rib.position.set(0, 2.38 - i * 0.16, 0);
    rib.rotation.set(Math.PI / 2, 0.3, 0);
    body.add(rib);
  }
  // chest cavity glow
  const cavity = new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 8), vein);
  cavity.position.set(0, 2.3, 0.09);
  cavity.scale.set(1, 1.4, 0.4);
  body.add(cavity);
  // neck
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.07, 0.4, 6), skin);
  neck.position.y = 2.72;
  body.add(neck);
  // head: elongated, featureless
  const head = new THREE.Group();
  head.position.y = 3.02;
  body.add(head);
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.16, 14, 12), skin);
  skull.scale.set(0.78, 1.5, 0.78);
  head.add(skull);
  const face = new THREE.Mesh(new THREE.SphereGeometry(0.135, 12, 10), std(0x120d0c));
  face.position.set(0, 0.01, 0.045);
  face.scale.set(0.72, 1.35, 0.5);
  head.add(face);
  // sockets
  for (const s of [-1, 1]) {
    const socket = new THREE.Mesh(new THREE.SphereGeometry(0.033, 8, 6), new THREE.MeshBasicMaterial({ color: 0x030202 }));
    socket.position.set(s * 0.052, 0.05, 0.13);
    head.add(socket);
    const ember = new THREE.Sprite(new THREE.SpriteMaterial({ color: 0xff2a16, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false }));
    ember.scale.setScalar(0.06);
    ember.position.copy(socket.position).add(new THREE.Vector3(0, 0, 0.02));
    head.add(ember);
  }
  // long arms
  const arms = [];
  for (const s of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(s * 0.22, 2.52, 0);
    body.add(shoulder);
    const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.045, 0.7, 4, 6), skin);
    upper.position.y = -0.38;
    shoulder.add(upper);
    const elbow = new THREE.Group();
    elbow.position.y = -0.76;
    shoulder.add(elbow);
    const fore = new THREE.Mesh(new THREE.CapsuleGeometry(0.035, 0.78, 4, 6), skin);
    fore.position.y = -0.4;
    elbow.add(fore);
    const hand = new THREE.Group();
    hand.position.y = -0.82;
    elbow.add(hand);
    for (let i = 0; i < 4; i++) {
      const finger = new THREE.Mesh(new THREE.CapsuleGeometry(0.009, 0.22 - i * 0.02, 3, 4), skin);
      finger.position.set((i - 1.5) * 0.028, -0.13, 0);
      finger.rotation.z = (i - 1.5) * 0.08;
      hand.add(finger);
    }
    shoulder.rotation.z = s * 0.16;
    arms.push({ shoulder, elbow });
  }
  // hanging tendrils
  const tendrils = [];
  for (let i = 0; i < 8; i++) {
    const pts = [];
    const a = (i / 8) * Math.PI * 2;
    for (let j = 0; j < 6; j++) {
      pts.push(new THREE.Vector3(Math.cos(a) * (0.08 + j * 0.03), 1.8 - j * 0.28, Math.sin(a) * (0.06 + j * 0.02)));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 18, 0.012, 4, false), dark);
    body.add(tube);
    tendrils.push(tube);
  }
  // aura
  const aura = new THREE.Sprite(new THREE.SpriteMaterial({ color: 0x8e0c06, transparent: true, opacity: 0.13, blending: THREE.AdditiveBlending, depthWrite: false }));
  aura.scale.setScalar(5.5);
  aura.position.y = 2.2;
  root.add(aura);

  let phase = 0;
  const update = (t, dt) => {
    phase += dt;
    body.position.y = Math.sin(t * 0.55) * 0.07;
    body.rotation.z = Math.sin(t * 0.31) * 0.035;
    arms.forEach(({ shoulder, elbow }, i) => {
      shoulder.rotation.x = Math.sin(t * 0.4 + i * 1.6) * 0.12 - 0.05;
      elbow.rotation.x = 0.18 + Math.sin(t * 0.52 + i) * 0.1;
    });
    head.rotation.y = Math.sin(t * 0.24) * 0.22;
    head.rotation.x = -0.06 + Math.sin(t * 0.37) * 0.04;
    tendrils.forEach((tube, i) => {
      tube.rotation.y = Math.sin(t * 0.3 + i) * 0.06;
    });
    aura.material.opacity = 0.1 + Math.sin(t * 0.8) * 0.035;
  };

  return { root, body, head, update };
}

export function addActor(sceneGroup, opts, pos = [0, 0, 0], rotY = 0) {
  const a = createPerson(opts);
  a.root.position.set(...pos);
  a.root.rotation.y = rotY;
  sceneGroup.add(a.root);
  return a;
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { buildScene } from './scenes.js';

const GRADE_SHADER = {
  uniforms: {
    tDiffuse: { value: null },
    uTime: { value: 0 },
    uResolution: { value: new THREE.Vector2(1, 1) },
    uGrain: { value: 0.055 },
    uVignette: { value: 0.62 },
    uAberration: { value: 1.0 },
    uTint: { value: new THREE.Color(1, 1, 1) },
    uSaturation: { value: 1.0 },
    uContrast: { value: 1.02 }
  },
  vertexShader: `
    varying vec2 vUv;
    void main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform float uTime, uGrain, uVignette, uAberration, uSaturation, uContrast;
    uniform vec2 uResolution;
    uniform vec3 uTint;
    varying vec2 vUv;

    float hash(vec2 p) {
      p = fract(p * vec2(123.34, 456.21));
      p += dot(p, p + 45.32);
      return fract(p.x * p.y);
    }

    void main() {
      vec2 uv = vUv;
      vec2 c = uv - 0.5;
      float d = length(c);
      vec2 dir = normalize(c + 1e-6) * uAberration * 0.0016 * d;
      vec3 col;
      col.r = texture2D(tDiffuse, uv + dir).r;
      col.g = texture2D(tDiffuse, uv).g;
      col.b = texture2D(tDiffuse, uv - dir).b;

      col *= uTint;
      float l = dot(col, vec3(0.2126, 0.7152, 0.0722));
      col = mix(vec3(l), col, uSaturation);
      col = (col - 0.5) * uContrast + 0.5;

      float grain = hash(uv * uResolution + fract(uTime) * 137.0) - 0.5;
      col += grain * uGrain * (0.55 + 0.45 * (1.0 - l));

      float vig = smoothstep(0.82, 0.22, d);
      col *= mix(1.0, vig, uVignette);

      gl_FragColor = vec4(max(col, 0.0), 1.0);
    }
  `
};

const ease = (x) => x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;

export class Engine {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({
      canvas, antialias: true, powerPreference: 'high-performance', alpha: false,
      stencil: false
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.55));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.05, 300);
    this.camera.position.set(0, 2, 12);

    this.sceneRoot = new THREE.Group();
    this.scene.add(this.sceneRoot);
    this.flashLight = new THREE.AmbientLight(0xb9cdf5, 0);
    this.scene.add(this.flashLight);
    this.hemi = new THREE.HemisphereLight(0x4a5b72, 0x0a0806, 0.28);
    this.scene.add(this.hemi);

    this.clock = new THREE.Clock();
    this.time = 0;
    this.paused = false;
    this.spec = null;
    this.sceneId = null;
    this.shotName = null;
    this.camT = 1;
    this.camDuration = 1;
    this.camFrom = { pos: new THREE.Vector3(), look: new THREE.Vector3(), fov: 40 };
    this.camTo = { pos: new THREE.Vector3(), look: new THREE.Vector3(), fov: 40 };
    this.lookCurrent = new THREE.Vector3(0, 2, 0);
    this.shake = 0;
    this.shakeTarget = 0;
    this.handheld = 0.35;
    this.flashLevel = 0;
    this.flashDecay = 0.9;
    this.flashColor = new THREE.Color(0xbfd4ff);
    this.reduceFlashes = false;
    this.grainOn = true;
    this.exploreCallbacks = null;
    this.hotspotHover = null;
    this.pointer = new THREE.Vector2(-10, -10);
    this.raycaster = new THREE.Raycaster();
    this.hotspotRings = [];
    this.lightningTimer = null;
    this.lastLightning = 0;

    this._setupComposer();
    this._bind();
    this.renderer.setAnimationLoop(() => this._tick());
  }

  _setupComposer() {
    const size = new THREE.Vector2(window.innerWidth, window.innerHeight);
    this.composer = new EffectComposer(this.renderer);
    this.composer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(this.renderPass);
    this.bloom = new UnrealBloomPass(size, 0.62, 0.7, 0.72);
    this.composer.addPass(this.bloom);
    this.grade = new ShaderPass(GRADE_SHADER);
    this.grade.uniforms.uResolution.value.set(window.innerWidth, window.innerHeight);
    this.composer.addPass(this.grade);
    this.output = new OutputPass();
    this.composer.addPass(this.output);
  }

  _bind() {
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('pointermove', (e) => {
      this.pointer.x = (e.clientX / window.innerWidth) * 2 - 1;
      this.pointer.y = -(e.clientY / window.innerHeight) * 2 + 1;
      if (this.exploreCallbacks) this._updateHover();
    });
    window.addEventListener('click', () => {
      if (this.exploreCallbacks?.onClick) {
        const hs = this._pickHotspot();
        if (hs) this.exploreCallbacks.onClick(hs);
      }
    });
  }

  resize() {
    const w = window.innerWidth, h = window.innerHeight;
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.55));
    this.renderer.setSize(w, h);
    this.composer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.composer.setSize(w, h);
    this.grade.uniforms.uResolution.value.set(w, h);
  }

  async setScene(id, { shot = null, instant = false } = {}) {
    this._disposeScene();
    this.sceneId = id;
    this.spec = buildScene(id);
    this.sceneRoot.add(this.spec.group);
    this.scene.fog = this.spec.fog || null;
    this.scene.background = this.spec.background || new THREE.Color(0x020203);
    this.scene.backgroundIntensity = this.spec.backgroundIntensity ?? 1;
    this.renderer.toneMappingExposure = this.spec.exposure ?? 1.05;
    this.bloom.strength = this.spec.bloom ?? 0.62;
    this.bloom.radius = this.spec.bloomRadius ?? 0.7;
    this.bloom.threshold = this.spec.bloomThreshold ?? 0.72;
    this.hemi.intensity = this.spec.hemi ?? 0.28;
    this.hemi.color.set(this.spec.hemiColor ?? 0x4a5b72);
    this.hemi.groundColor.set(this.spec.hemiGround ?? 0x080706);
    this.grade.uniforms.uTint.value.set(this.spec.tint ?? 0xffffff);
    this.grade.uniforms.uGrain.value = this.grainOn ? (this.spec.grain ?? 0.055) : 0;
    this.grade.uniforms.uVignette.value = this.spec.vignette ?? 0.62;
    this.grade.uniforms.uSaturation.value = this.spec.saturation ?? 1.0;
    this.grade.uniforms.uContrast.value = this.spec.contrast ?? 1.02;
    this.grade.uniforms.uAberration.value = this.spec.aberration ?? 1.0;

