42:     uniforms: {
43:       uTop: { value: new THREE.Color(top) },
44:       uBottom: { value: new THREE.Color(bottom) },
45:       uHorizon: { value: new THREE.Color(horizon || bottom) },
46:       uTime: { value: 0 },
47:       uCloud: { value: opts.cloud ?? 0.0 },
48:       uCloudColor: { value: new THREE.Color(opts.cloudColor || 0x0d1a22) }
49:     },
50:     vertexShader: `
51:       varying vec3 vWorld;
52:       varying vec2 vUv;
53:       void main() {
54:         vUv = uv;
55:         vWorld = (modelMatrix * vec4(position, 1.0)).xyz;
56:         gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
57:       }`,
58:     fragmentShader: `
59:       uniform vec3 uTop, uBottom, uHorizon, uCloudColor;
60:       uniform float uTime, uCloud;
61:       varying vec3 vWorld;
62:       varying vec2 vUv;
63:       float hash(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
64:       float noise(vec2 p){
65:         vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
66:         return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);
67:       }
68:       void main(){
69:         float h = clamp(normalize(vWorld).y, -0.2, 1.0);
70:         vec3 col = mix(uBottom, uTop, smoothstep(-0.02, 0.62, h));
71:         col = mix(col, uHorizon, pow(1.0 - clamp(h + 0.02, 0.0, 1.0), 6.0) * 0.55);
72:         vec2 cp = vUv * vec2(6.0, 12.0);
73:         float n = noise(cp + vec2(uTime * 0.012, 0.0)) * 0.6 + noise(cp * 2.3 - uTime * 0.006) * 0.4;
74:         float band = smoothstep(0.02, 0.3, h) * (1.0 - smoothstep(0.55, 0.95, h));
75:         col = mix(col, uCloudColor, n * band * uCloud);
76:         gl_FragColor = vec4(col, 1.0);
77:       }`
