.letterbox-top { top: 0; }
.letterbox-bottom { bottom: 0; }
body.wide .letterbox { height: 7vh; }

#flash {
  position: absolute;
  inset: 0;
  background: #eaf2ff;
  opacity: 0;
  pointer-events: none;
  z-index: 25;
  mix-blend-mode: screen;
}
#flash.fire { background: #ff4a2e; }
#flash.blood { background: #d2141f; }

#damage {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 12;
  opacity: 0;
  box-shadow: inset 0 0 22vw rgba(120, 0, 8, 0.9);
  background: radial-gradient(ellipse at center, transparent 45%, rgba(90, 0, 4, 0.55) 100%);
  transition: opacity 0.7s ease;
}

#fade {
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 1;
  pointer-events: none;
  z-index: 40;
  transition: opacity 1.15s ease;
}
#fade.visible { opacity: 1; }
#fade.clear { opacity: 0; }

#fade-caption {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 41;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(18px, 2vw, 30px);
  letter-spacing: 0.14em;
  color: rgba(232, 226, 212, 0.7);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.7s ease;
  white-space: nowrap;
  text-transform: uppercase;
}
#fade-caption.on { opacity: 1; }

/* ---------------- hud ---------------- */

#hud {
  position: absolute;
  inset: 0;
#inspect p { margin: 0 0 20px; font-size: 16px; line-height: 1.55; font-weight: 300; color: rgba(232, 226, 212, 0.75); letter-spacing: 0.015em; }
.inspect-foot { display: flex; justify-content: space-between; font-size: 9px; letter-spacing: 0.3em; color: rgba(232, 226, 212, 0.36); }
#inspect-count { color: var(--gold); }

/* ---------------- toast ---------------- */

#toast {
  position: absolute;
  top: calc(7vh + 34px);
  left: 50%;
  transform: translate(-50%, -14px);
  z-index: 28;
  font-size: 10px;
  letter-spacing: 0.4em;
  color: var(--gold);
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 0.5s ease, transform 0.5s ease;
  pointer-events: none;
  text-align: center;
  text-shadow: 0 2px 12px #000;
  white-space: nowrap;
}
#toast.on { opacity: 1; transform: translate(-50%, 0); }

/* ---------------- chapter card ---------------- */

#ending-stats { display: flex; justify-content: center; gap: 34px; margin-bottom: 34px; flex-wrap: wrap; }
.ending-stat { font-size: 9px; letter-spacing: 0.3em; color: rgba(232, 226, 212, 0.34); text-transform: uppercase; }
.ending-stat b { display: block; font-family: var(--serif); font-weight: 500; font-size: 20px; letter-spacing: 0.1em; color: var(--gold); margin-top: 6px; }
.ending-buttons { display: flex; justify-content: center; gap: 26px; flex-wrap: wrap; }
.ending-buttons .menu-item { width: 210px; }

/* ---------------- loading ---------------- */

#loading {
  position: absolute;
  inset: 0;
  z-index: 60;
  background: #030303;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: opacity 1.1s ease, visibility 1.1s;
}
#loading.done { opacity: 0; visibility: hidden; }
.load-mark {
  width: 52px; height: 52px;
  border: 1px solid rgba(200, 165, 107, 0.5);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--serif); font-size: 22px; letter-spacing: 0.1em; color: var(--gold);
  margin-bottom: 26px;
  animation: loadPulse 2.4s ease-in-out infinite;
}
@keyframes loadPulse { 0%,100% { box-shadow: 0 0 0 0 rgba(200,165,107,0.08); } 50% { box-shadow: 0 0 46px 0 rgba(200,165,107,0.18); } }
.load-title { font-family: var(--serif); font-size: 12px; letter-spacing: 0.6em; color: rgba(232, 226, 212, 0.55); margin-bottom: 30px; }
.load-bar { width: 220px; height: 1px; background: rgba(232, 226, 212, 0.12); overflow: hidden; }
#load-fill { display: block; height: 100%; width: 0; background: var(--gold); transition: width 0.4s ease; }
.load-status { margin-top: 16px; font-size: 9px; letter-spacing: 0.38em; color: rgba(232, 226, 212, 0.3); }

.hidden { }
.screen.hidden, #hud.hidden, #subtitles.hidden, #choices.hidden, #qte.hidden,
#explore.hidden, #inspect.hidden, #chapter-card.hidden { pointer-events: none; }

/* ---------------- responsive ---------------- */

@media (max-width: 980px) {
  .letterbox { height: 5vh; }
  #hud { padding: calc(5vh + 14px) 4vw; }
  #subtitles { left: 4vw; bottom: calc(5vh + 36px); max-width: 86vw; }
  #choices { right: 4vw; left: 4vw; width: auto; bottom: calc(5vh + 36px); }
  .title-wrap { left: 5vw; width: 88vw; bottom: 9vh; }
  .title-side { display: none; }
  .title-menu { width: 280px; }
  .title-foot { gap: 14px; flex-wrap: wrap; font-size: 7px; }
  .pause-panel { grid-template-columns: 1fr; row-gap: 24px; padding: 28px; }
  .pause-decisions { grid-column: 1; grid-row: auto; border-left: 0; padding-left: 0; border-top: 1px solid rgba(232,226,212,0.1); padding-top: 22px; }
  #inspect { width: min(440px, 82vw); }
  .ending-buttons .menu-item { width: 180px; }
}

@media (max-height: 700px) {
  .title-tagline { margin-top: 16px; }
  .title-menu { margin-top: 18px; }
  .title-foot { margin-top: 18px; }
  .game-title span { font-size: clamp(46px, 7.4vw, 100px); }
  .game-title span:nth-child(2) { font-size: clamp(60px, 9.6vw, 140px); }
  .game-title span:nth-child(3) { font-size: clamp(34px, 5.4vw, 80px); }
}

@media (prefers-reduced-motion: reduce) {
  .noise { animation: none; }
  * { scroll-behavior: auto; }
}

